import{_ as t,C as n,o as i,c as o,E as s,a2 as r}from"./chunks/framework.Cm6XCzck.js";const b=JSON.parse('{"title":"Weekly 006 — 权限需要血缘链","description":"","frontmatter":{"title":"Weekly 006 — 权限需要血缘链","date":"2026-08-23","column":"digital-employee","category":"weekly","article_type":"research-brief","edition":"research-center","research_question":"当 Agent 状态经过压缩、恢复、委派、缓存、规范化或重建后继续存在时，哪些证据也必须一起保留下来，系统才能确认它现在仍然被授权使用？","summary":"过去七天 21 篇证据已验证 Daily Research 反复暴露同一种故障：值能够穿过各种状态变换继续存在，但原先赋予它权限的依据未必一起存在。可靠 Agent Runtime 需要保持 Provenance 的准入机制，让来源、范围、策略上下文与变换血缘随运行状态一起传递，并在真正使用时重新核验。","sources":["2026-08-17 至 2026-08-23 Daily Runtime V5 publications","research/intelligence/p2-runs/2026/08/2026-08-23-p2-special.json"],"evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true,"cover":"/assets/covers/weekly-006-authority-needs-lineage-cover-v2.png"},"headers":[],"relativePath":"zh/research/weekly/weekly-006.md","filePath":"zh/research/weekly/weekly-006.md","lastUpdated":1787666502000}'),l={name:"zh/research/weekly/weekly-006.md"};function p(c,e,d,u,h,m){const a=n("ArticleCover");return i(),o("div",null,[s(a,{image:"/assets/covers/weekly-006-authority-needs-lineage-cover-v2.png",kicker:"Weekly Research · 006",title:"权限需要血缘链",summary:"状态可以穿过变换继续存在，但原先使它有效的权限未必一起保留。",version:"W006",status:"Published 2026-08-23",languageHref:"/en/research/weekly/weekly-006",languageLabel:"English"}),e[0]||(e[0]=r(`<h1 id="weekly-006-—-权限需要血缘链" tabindex="-1">Weekly 006 — 权限需要血缘链 <a class="header-anchor" href="#weekly-006-—-权限需要血缘链" aria-label="Permalink to &quot;Weekly 006 — 权限需要血缘链&quot;">​</a></h1><p>上一期 Weekly 的判断是：每一次重要交接都需要带证据的回执。本周 21 篇证据已验证 Daily Research 把问题推进了一层：<strong>状态即使安全完成了交接，也可能在后续变换中重新变得不安全。</strong></p><p>Agent Runtime 会压缩 Transcript、重建 History、恢复 Checkpoint、刷新凭据、合并 Policy、缓存 Plugin、规范化 Identifier、导入 Tool Output、继承执行环境状态，并把工作委派给下游 Agent。这些机制之所以有价值，就是因为它们可以保存连续性。但连续性也会制造一种危险错觉：只要一个值还存在，当初让它可信、可执行的理由好像也还存在。</p><p>本周的证据反复说明，这个推断不成立。</p><p>Command Name 可以继续存在，但 Repository Configuration 已经改变它真正会执行什么；Human Approval 可以继续存在，但批准者是谁、为什么有权批准却丢失了；Child-agent Role 可以在 Resume 后重建，但有效权限可能意外扩大；OAuth Refresh 成功后新 Token 已在内存里，却可能没有持久写入；Cache Miss 可以继续存在，但并不能证明真实资源已经删除；最新 Checkpoint 可以存在，但授权它的 Policy 已经变化；Canonical Identifier 可以存在，但 Lifecycle 操作仍可能在非规范别名上发生竞争。</p><p>机制不同，控制故障却是同一个：</p><blockquote><p><strong>值继续存在，不等于权限结论继续有效。</strong></p></blockquote><p>因此，本周形成的新判断是：</p><blockquote><p><strong>可靠 Agent 系统需要“保持 Provenance 的准入机制”。运行状态不应只有 Value，还应保留让这个 Value 可以安全使用的 Origin、Scope、Policy Context、Transformation Lineage 与当前 Admission Evidence。状态变换可以保持或收窄权限，但不能静默扩大权限。</strong></p></blockquote><h2 id="证据范围" tabindex="-1">证据范围 <a class="header-anchor" href="#证据范围" aria-label="Permalink to &quot;证据范围&quot;">​</a></h2><p>本次综合只使用 <strong>2026-08-17 至 2026-08-23</strong> 在完整 V5 Publication 链路达到已核验终态后发布的 Daily Research。七个 Daily Runtime 日全部达到 <code>publication = Completed</code>，数字员工、行业架构、开源工程三个正式栏目合计形成 <strong>21 篇 Daily Research</strong>。</p><table tabindex="0"><thead><tr><th>日期</th><th>数字员工</th><th>行业架构</th><th>开源工程</th></tr></thead><tbody><tr><td>8 月 17 日</td><td>Selective Fail-closed API</td><td>Environment-owned Policy</td><td>Compact Transcript Evidence</td></tr><tr><td>8 月 18 日</td><td>Accountable Human Approval</td><td>Persistence and Reconciliation</td><td>Trace-to-effect Evidence</td></tr><tr><td>8 月 19 日</td><td>Monotonic Delegation Authority</td><td>Delivery-context Separation</td><td>OAuth Refresh Split Commit</td></tr><tr><td>8 月 20 日</td><td>Command Name 不是 Execution Authority</td><td>History 不是 Transfer Contract</td><td>Visible 不是 Durable</td></tr><tr><td>8 月 21 日</td><td>Useful Context 不是 Memory Authority</td><td>Approval 必须指明 Approver</td><td>Trust the Run, Not Inherited Secrets</td></tr><tr><td>8 月 22 日</td><td>Authorization Needs Provenance</td><td>Protected Constraints, Reviewable Grants</td><td>Missing Cache Entry 不是 Deletion Evidence</td></tr><tr><td>8 月 23 日</td><td>Resume Recency 不是 Authority</td><td>Creation Provenance Survives Resume</td><td>Canonicalize Before Lifecycle</td></tr></tbody></table><p>这是一组密集的工程证据样本，不代表整个行业已经形成统一实践。本周真正值得保留的是：在相互独立的研究对象上，<strong>同一个状态与权限边界反复出现。</strong></p><p>P2 专项通道本周另外检查了 4 个到期的 <code>biweekly-or-release</code> 对象，全部完成终态检查；2 个 monthly 对象本周不到期；没有对象达到 5 分触发阈值，因此没有运行完整 P2 Special Study。检查中还发现一个有价值的治理问题：<code>agent-style</code> 在 8 月 16 日保存的检查点落后于一个其实早在前次运行前就已经存在的 README 澄清提交。本周因此只纠正 Checkpoint Identity，不把旧提交错误包装成本周新增变化。</p><h2 id="反复出现的故障-状态变换时-provenance-被丢掉了" tabindex="-1">反复出现的故障：状态变换时 Provenance 被丢掉了 <a class="header-anchor" href="#反复出现的故障-状态变换时-provenance-被丢掉了" aria-label="Permalink to &quot;反复出现的故障：状态变换时 Provenance 被丢掉了&quot;">​</a></h2><p>上一期关注的是不同 Owner 之间的交接。本周说明，同样的危险也会发生在一个 Owner 内部的状态处理链里。</p><p>Runtime 可以先接收到一个有效事实，然后在后续转换时把它与原本赋予它意义的条件拆开。</p><h3 id="名字不等于当前真正会执行的行为" tabindex="-1">名字不等于当前真正会执行的行为 <a class="header-anchor" href="#名字不等于当前真正会执行的行为" aria-label="Permalink to &quot;名字不等于当前真正会执行的行为&quot;">​</a></h3><p>8 月 20 日数字员工研究了一个看似简单的问题：一个 Command 可以保留熟悉、看起来安全的名字，但 Repository Configuration 已经改变这个名字最终解析出的真实执行。</p><p>因此，如果 Policy 只绑定 Command Label，它的控制能力会比表面上更弱。Label 只是 Identifier；真正的 Execution Authority 取决于解析后的命令、Configuration Source、Working Context 与适用的 Approval Policy。</p><p>更一般的形式是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>稳定 Label</span></span>
<span class="line"><span>+ 已变化 Resolution Context</span></span>
<span class="line"><span>≠ 稳定 Authority</span></span></code></pre></div><p>同样的问题也会出现在 Plugin Alias、Tool Name、Model Routing Label、Saved Workflow Name 与 Remote Session Identifier。稳定 Key 有助于关联，但 Policy 应绑定 Effective Operation，而不是只绑定熟悉的名字。</p><h3 id="human-answer-不等于-human-authority-proof" tabindex="-1">Human Answer 不等于 Human Authority Proof <a class="header-anchor" href="#human-answer-不等于-human-authority-proof" aria-label="Permalink to &quot;Human Answer 不等于 Human Authority Proof&quot;">​</a></h3><p>8 月 18 日与 8 月 21 日的研究从两个方向指向同一边界。</p><p>一篇说明远程 A2A Peer 不能替代真人满足危险动作的 Human Confirmation；另一篇说明 Approval Trust 必须绑定真实 Approving Principal，而不能只绑定 Transport Metadata。</p><p><code>approved</code> 这样的字符串、被标成 <code>human</code> 的 Callback、从可信 Channel 送达的消息，都可能保留“回答”，却没有保留“为什么这个回答有权生效”的证据。</p><p>更可靠的 Approval Record 至少应能保留：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>occurrence_id</span></span>
<span class="line"><span>approver_principal</span></span>
<span class="line"><span>authority_scope</span></span>
<span class="line"><span>policy_version</span></span>
<span class="line"><span>decision</span></span>
<span class="line"><span>source_provenance</span></span></code></pre></div><p>这不意味着所有审批都要建立复杂身份基础设施。真正的要求是：Runtime 不能根据 Message Shape 或 Transport Path 静默推断批准者权限。</p><h3 id="delegation-在-resume-与-customization-后必须保持权限单调" tabindex="-1">Delegation 在 Resume 与 Customization 后必须保持权限单调 <a class="header-anchor" href="#delegation-在-resume-与-customization-后必须保持权限单调" aria-label="Permalink to &quot;Delegation 在 Resume 与 Customization 后必须保持权限单调&quot;">​</a></h3><p>8 月 19 日数字员工研究了 Child-agent Role 自定义与 Resume。核心不变量是 Monotonicity：委派可以保持或缩小权限，但 Representation Change 本身不应让权限扩大。</p><p>这在 Checkpoint Restore 后尤其重要。恢复中的 Child Agent 可能重新构造 Role Label、Tool、Context 与 Pending Work。如果 Effective Permission Envelope 从不完整或过期字段重建，Resume 后的表示可能反而比原始执行更宽松。</p><p>一个有用的不变量是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Authority(after transform) ⊆ Authority(before transform)</span></span></code></pre></div><p>除非系统重新接纳一个明确的新 Grant。</p><p>这条规则可以同时解释 Role Customization、Policy Merge、Saved Approval、Connector Capability Reconstruction 与 Remote-session Resume。</p><h2 id="continuity-mechanism-需要独立-admission-boundary" tabindex="-1">Continuity Mechanism 需要独立 Admission Boundary <a class="header-anchor" href="#continuity-mechanism-需要独立-admission-boundary" aria-label="Permalink to &quot;Continuity Mechanism 需要独立 Admission Boundary&quot;">​</a></h2><p>一个常见工程错误，是把 Persistence 当作最后的 Correctness Property。</p><p>本周证据说明，Persistence 只解决一个问题：<strong>Value 有没有活下来？</strong> 它没有回答：<strong>这个 Value 现在还能不能被使用？</strong></p><h3 id="refresh-成功不等于-credential-state-已持久提交" tabindex="-1">Refresh 成功不等于 Credential State 已持久提交 <a class="header-anchor" href="#refresh-成功不等于-credential-state-已持久提交" aria-label="Permalink to &quot;Refresh 成功不等于 Credential State 已持久提交&quot;">​</a></h3><p>8 月 19 日开源工程把 OAuth Refresh 分析成一个 Split Commit。</p><p>Provider 可以成功签发新 Credential，而本地 Durable Persistence 仍然失败。这时内存里已经有有效新 Token，但 Durable Store 还停在旧状态。如果系统把这个失败隐藏掉，之后的 Worker 可能从一个从未和成功 Refresh Event 对齐的 Credential State 继续工作。</p><p>正确边界应明确保留：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>provider refresh accepted</span></span>
<span class="line"><span>≠ credential state durably committed</span></span></code></pre></div><p>Fail-visible 设计不会假装整个 Refresh Transaction 是原子的，而是显式记录这次 Split。</p><p>这同样适用于 Approval Persistence、Checkpoint Write、Session Rebinding、Artifact Publication 与 Tool-result Caching。</p><h3 id="visible-不等于-durable" tabindex="-1">Visible 不等于 Durable <a class="header-anchor" href="#visible-不等于-durable" aria-label="Permalink to &quot;Visible 不等于 Durable&quot;">​</a></h3><p>8 月 20 日开源工程从 Artifact Publication 得到同样结论。先隔离 Pending State，再 Atomic Rename，可以防止消费者把部分发布的版本误认为权威版本。</p><p>这个判断并不局限于文件系统：</p><blockquote><p><strong>Visibility 是比 Durable Admission 更弱的事实。</strong></p></blockquote><p>一个值可能已经可以读取，但仍然是 Provisional；UI 可以显示一个 Task，但 Authoritative Record 还未提交；Remote Object 可以被发现，但 Reconciliation 还没确认 Ownership；Model Output 可以已经产生，但还没跨过 Evidence Gate。</p><p>因此系统更适合拥有 <code>pending</code>、<code>admitted</code>、<code>committed</code>、<code>verified</code>、<code>superseded</code> 这样的显式状态，而不是用一个重载的 “exists” 表示一切。</p><h3 id="recency-不等于-authority" tabindex="-1">Recency 不等于 Authority <a class="header-anchor" href="#recency-不等于-authority" aria-label="Permalink to &quot;Recency 不等于 Authority&quot;">​</a></h3><p>8 月 23 日数字员工把这个问题收紧到 Resume。</p><p>最新 Checkpoint 往往最有操作价值，因为它能减少恢复成本。但 “latest” 是排序事实，不是权限事实。最新 Snapshot 仍可能带着已撤销 Grant、旧 Principal Binding、失效假设，或者由过时 Policy Epoch 创建的状态。</p><p>因此 Resume 必须分开回答：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>哪个 State 最新？</span></span>
<span class="line"><span>哪个 State 现在仍可被 Admission？</span></span></code></pre></div><p>只回答第一个问题的 Runtime 可以很快，但不能算受治理。</p><h2 id="信息可以有用-却不必成为授权状态" tabindex="-1">信息可以有用，却不必成为授权状态 <a class="header-anchor" href="#信息可以有用-却不必成为授权状态" aria-label="Permalink to &quot;信息可以有用，却不必成为授权状态&quot;">​</a></h2><p>本周多篇研究都在区分 Information Utility 与 Operational Authority。</p><h3 id="external-tool-output-默认不是-reusable-memory" tabindex="-1">External Tool Output 默认不是 Reusable Memory <a class="header-anchor" href="#external-tool-output-默认不是-reusable-memory" aria-label="Permalink to &quot;External Tool Output 默认不是 Reusable Memory&quot;">​</a></h3><p>8 月 21 日数字员工区分独立 External Tool Output 与可复用 Agent Memory。</p><p>Tool Output 可以是非常有价值的 Context。但把它提升为 Memory，会改变它的生命周期：它可能被未来 Task 重放、被其他任务看到，甚至被当成 Durable Background Truth。</p><p>因此，这个 Promotion 应当是带 Provenance、Scope 与 Expiry 的 Admission Operation，而不是 Tool 返回一个值之后自动发生的副作用。</p><p>一个 Context Item 可以保持有用，而不必变成长寿命 Authority。</p><h3 id="history-不是-transfer-contract" tabindex="-1">History 不是 Transfer Contract <a class="header-anchor" href="#history-不是-transfer-contract" aria-label="Permalink to &quot;History 不是 Transfer Contract&quot;">​</a></h3><p>8 月 20 日行业架构研究跨 Agent History Reconstruction。历史重放可以恢复 Context，但携带 Credential 的 Control Call 应被 Scrub，而不是作为普通 Conversation State 一起转移。</p><p>这里必须区分：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>replayable history</span></span>
<span class="line"><span>≠ transferable capability</span></span></code></pre></div><p>前一个 Worker 曾经使用过某个 Token、Connector Grant、Approval 或 Control Instruction，并不意味着这些 Capability 自动属于接收 Worker 的可转移 Context。</p><p>同理也适用于 Shell Environment Variable、API Secret、Temporary Approval Token 与 Provider Session Cookie。</p><h3 id="delivery-与-model-context-是不同存储域" tabindex="-1">Delivery 与 Model Context 是不同存储域 <a class="header-anchor" href="#delivery-与-model-context-是不同存储域" aria-label="Permalink to &quot;Delivery 与 Model Context 是不同存储域&quot;">​</a></h3><p>8 月 19 日行业架构把异步 User Delivery 与 Model Input Context 分开，同时保留可回放 Delivery Metadata。</p><p>这也是一个 Provenance Boundary。一个 Message 可能对 Delivery Audit 很重要，却不应进入未来 Model Context；反过来，Model Context 可以包含内部推理状态，但绝不能自动成为用户可见 Delivery History。</p><p>两个 Store 分开后，“曾经发送过”就不会再自动等于“应该继续影响未来执行”。</p><h2 id="absence、cache-state-与-canonical-identity-需要更强语义" tabindex="-1">Absence、Cache State 与 Canonical Identity 需要更强语义 <a class="header-anchor" href="#absence、cache-state-与-canonical-identity-需要更强语义" aria-label="Permalink to &quot;Absence、Cache State 与 Canonical Identity 需要更强语义&quot;">​</a></h2><p>并非所有危险 Transformation 都是在增加数据。有些发生在删除、缺失或规范化时。</p><h3 id="missing-不等于-deleted" tabindex="-1">Missing 不等于 Deleted <a class="header-anchor" href="#missing-不等于-deleted" aria-label="Permalink to &quot;Missing 不等于 Deleted&quot;">​</a></h3><p>8 月 22 日开源工程研究了带 Account Scope、Serialization 与 Generation Guard 的 Plugin-cache Reconciliation。</p><p>核心负面事实很简单：Cache Entry 缺失，不证明真实 Plugin 已经删除。Cache 可能过期、不完整、来自另一个 Account，或者刚刚被旧 Generation 覆盖。</p><p>这是本周判断的 Negative-evidence 版本：</p><blockquote><p><strong>没有 Provenance 的 Absence，不是权威 Absence。</strong></p></blockquote><p>Deletion、Revocation 与 Non-existence 都是有后果的结论。它们往往需要 Authoritative Source Read、Tombstone、Generation Number 或 Reconciled Snapshot，而不能从一次 Local Miss 推断出来。</p><h3 id="lifecycle-之前先-canonicalize" tabindex="-1">Lifecycle 之前先 Canonicalize <a class="header-anchor" href="#lifecycle-之前先-canonicalize" aria-label="Permalink to &quot;Lifecycle 之前先 Canonicalize&quot;">​</a></h3><p>8 月 23 日开源工程说明，逻辑等价的 Identifier 应在 Lifecycle Operation 竞争之前完成 Canonicalization。</p><p>如果不这样做，两个 Alias 可能为同一个底层 Resource 建出两条看似独立的 Ownership Path，Lock、Cleanup、Restart、Cache Key 与 Deduplication 都可能对 Representation 工作，而不是对 Identity 工作。</p><p>因此 Canonicalization 不是 Cosmetic Normalization，而是一道决定“哪个身份真正参与 Lifecycle”的 Admission Step。</p><p>但它仍然不是全部：Canonical Identity 依然需要 Provenance、Scope 与当前 Policy。</p><h2 id="一个可复用模型-provenance-preserving-admission" tabindex="-1">一个可复用模型：Provenance-Preserving Admission <a class="header-anchor" href="#一个可复用模型-provenance-preserving-admission" aria-label="Permalink to &quot;一个可复用模型：Provenance-Preserving Admission&quot;">​</a></h2><p>本周可以收敛成一个紧凑控制模型。</p><p>每一个有操作意义的事实，都可以理解为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>OperationalFact = {</span></span>
<span class="line"><span>  value,</span></span>
<span class="line"><span>  origin,</span></span>
<span class="line"><span>  principal,</span></span>
<span class="line"><span>  scope,</span></span>
<span class="line"><span>  policy_epoch,</span></span>
<span class="line"><span>  occurrence_id,</span></span>
<span class="line"><span>  transform_lineage,</span></span>
<span class="line"><span>  durability_state,</span></span>
<span class="line"><span>  verification_state</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>并不是每个系统都必须字面保存所有字段。重点是语义：Runtime 不只要知道“现在的值是什么”，还要知道“为什么这个值有资格表达下一个组件准备赋予它的意义”。</p><p>一个受治理 Transformation 可以是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>input fact</span></span>
<span class="line"><span>→ transform</span></span>
<span class="line"><span>→ preserve provenance</span></span>
<span class="line"><span>→ narrow or preserve scope</span></span>
<span class="line"><span>→ revalidate policy-sensitive fields</span></span>
<span class="line"><span>→ admit output fact</span></span></code></pre></div><p>危险版本则是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>input value</span></span>
<span class="line"><span>→ transform</span></span>
<span class="line"><span>→ output value</span></span>
<span class="line"><span>→ assume old authority still applies</span></span></code></pre></div><p>用这个模型回看本周机制，会发现它们其实高度统一：</p><ul><li>Selective Fail-closed Parsing 防止 Policy Field 被静默丢失；</li><li>Environment-owned Variable Policy 保留 Execution Context 来自哪里；</li><li>Compact Transcript Presentation 保留紧凑视图背后的完整 Evidence；</li><li>Named Approver Identity 保留是谁授予了权限；</li><li>Monotonic Delegation 防止 Transform 扩大 Scope；</li><li>Split-commit Visibility 保留 Credential “已签发”与“已持久化”的区别；</li><li>Atomic Publication 保留 Artifact “可见”与“已准入”的区别；</li><li>Memory Admission 保留 Useful Context 与 Durable Background State 的区别；</li><li>Generation-guarded Cache Reconciliation 保留 Snapshot Provenance；</li><li>Resume Re-admission 保留 Newest State 与 Currently Valid State 的区别；</li><li>Canonicalization 在并发开始前确定唯一 Lifecycle Identity。</li></ul><h2 id="相比上一期-新的增量是什么" tabindex="-1">相比上一期，新的增量是什么 <a class="header-anchor" href="#相比上一期-新的增量是什么" aria-label="Permalink to &quot;相比上一期，新的增量是什么&quot;">​</a></h2><p>Weekly 005 提出了 Ownership Boundary 上的 Evidence-bearing Handoff Receipt。Weekly 006 并不替代它，而是把同一要求推进到 State Machine 内部。</p><p>Handoff Receipt 回答：</p><blockquote><p>一个 Owner 到另一个 Owner，究竟转移了什么事实和权限？</p></blockquote><p>Provenance-preserving Admission 回答：</p><blockquote><p>接收方把这个 Fact 转换、缓存、压缩、恢复或重建之后，现在究竟还有哪些权限仍然有效？</p></blockquote><p>两者合起来得到更强的不变量：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Authority 必须同时跨 Transfer 与 Transformation 保持可追溯。</span></span></code></pre></div><p>一个系统可以有很完整的 Inter-service Receipt，却因为 Local Resume Code 丢掉 Policy Epoch 而失败；也可以有完美 Checkpoint Lineage，却因为 Remote Handoff 没有记录真正 Approving Principal 而失败。长期 Agent 需要两者同时成立。</p><h2 id="这个模型仍然解决不了的矛盾" tabindex="-1">这个模型仍然解决不了的矛盾 <a class="header-anchor" href="#这个模型仍然解决不了的矛盾" aria-label="Permalink to &quot;这个模型仍然解决不了的矛盾&quot;">​</a></h2><h3 id="full-lineage-与-operational-cost" tabindex="-1">Full Lineage 与 Operational Cost <a class="header-anchor" href="#full-lineage-与-operational-cost" aria-label="Permalink to &quot;Full Lineage 与 Operational Cost&quot;">​</a></h3><p>记录每一次 Transformation 会变得昂贵、难读。目标不应该是默认把所有系统都变成 Universal Event Sourcing。</p><p>更实际的原则是 Risk-based：对会影响 Execution Authority、External Side Effect、Durable Memory、Credential、Identity 与 Policy 的事实保留强 Lineage；普通信息变换可以使用更轻 Telemetry。</p><h3 id="revalidation-与-availability" tabindex="-1">Revalidation 与 Availability <a class="header-anchor" href="#revalidation-与-availability" aria-label="Permalink to &quot;Revalidation 与 Availability&quot;">​</a></h3><p>Fresh Authorization Check 在 Network Partition 或 Provider Outage 时可能失败。对于高后果动作，Fail Closed 是合理的；但并不是所有 Read-only Operation 都需要同等标准。</p><p>真正难点是声明清楚：哪些 Fact 必须重新 Admission，哪些可以安全使用有界 Cached Evidence。</p><h3 id="canonical-identity-与系统演进" tabindex="-1">Canonical Identity 与系统演进 <a class="header-anchor" href="#canonical-identity-与系统演进" aria-label="Permalink to &quot;Canonical Identity 与系统演进&quot;">​</a></h3><p>Canonicalization 假设存在稳定映射，但真实系统会 Rename Resource、迁移 Account、合并 Identity。</p><p>因此 Canonical Identity 也需要 Versioned Mapping Evidence，而不是永远不变的一条字符串。</p><h3 id="monotonic-authority-与合法权限升级" tabindex="-1">Monotonic Authority 与合法权限升级 <a class="header-anchor" href="#monotonic-authority-与合法权限升级" aria-label="Permalink to &quot;Monotonic Authority 与合法权限升级&quot;">​</a></h3><p>有时 Authority 确实应该扩大：Human Grant Exception、Administrator Unlock Tool，或者 Workflow 进入 Privileged Phase。</p><p>规则并不是“权限永远不能增加”，而是“权限不能因为 Representation Change 自己变大”。权限扩张必须来自一个新的 Explicit Grant，并带自己的 Provenance。</p><h2 id="预测" tabindex="-1">预测 <a class="header-anchor" href="#预测" aria-label="Permalink to &quot;预测&quot;">​</a></h2><p>以下是 Research Center 基于重复机制形成的解释，不是任何单一 Daily Source 的原话。</p><ol><li><strong>Resume Protocol 会越来越多暴露 Policy Epoch。</strong> Checkpoint ID 本身不足以支撑受治理恢复。</li><li><strong>Approval Record 会逐步变成 Principal-bound Artifact。</strong> 系统会区分 Decision Text 与“谁有权做出这个决定”的证据。</li><li><strong>Agent Memory 会出现显式 Admission Metadata。</strong> 在高可靠 Runtime 中，Tool Output 与 Delivery History 不再自动提升为 Durable Memory。</li><li><strong>Credential Refresh API 会显式暴露 Split-commit State。</strong> “已刷新但未持久化”会成为一等可恢复状态。</li><li><strong>Cache 会携带 Generation 与 Authority Provenance。</strong> 除非 Cache 被证明是 Authoritative Complete Snapshot，否则 Cache Miss 会被理解成 Uncertainty。</li><li><strong>Canonical Identity 会更早进入 Lifecycle Control。</strong> Lock、Deduplication 与 Ownership 会更倾向于绑定 Canonical Resource Identity，而不是用户可见 Alias。</li><li><strong>Compact Audit View 会保留回到 Full Evidence 的链接。</strong> Human-readable Summary 不会再被视为 Replayable Evidence 的替代品。</li></ol><h2 id="开放问题" tabindex="-1">开放问题 <a class="header-anchor" href="#开放问题" aria-label="Permalink to &quot;开放问题&quot;">​</a></h2><ul><li>跨 Agent、Tool 与 Connector，最值得标准化的最小 Provenance Envelope 是什么？</li><li>哪些 Policy 变化必须让已 Admission 的 State 在 Resume 时失效？</li><li>Runtime 如何证明多次 Transform 之后 Authority 一直单调不扩张？</li><li>Local Cache 要满足什么条件，Absence 才能升级为权威 Negative Evidence？</li><li>Approval Provenance 可以复用多久，什么事件应该撤销它？</li><li>Account Migration、Provider Rebinding 与 Resource Rename 后 Canonical Identity 如何保持稳定？</li><li>哪些 State Transformation 值得 Durable Lineage，哪些只需要 Transient Telemetry？</li><li>Runtime 如何表达“Value 仍有效，但 Authority 已失效”，同时又不丢掉这个 Context 的信息价值？</li></ul><h2 id="下一周研究优先级" tabindex="-1">下一周研究优先级 <a class="header-anchor" href="#下一周研究优先级" aria-label="Permalink to &quot;下一周研究优先级&quot;">​</a></h2><p>三个具体实验可以继续检验这个模型。</p><p><strong>第一，测试 Policy Change 下的 Resume。</strong> 在 Policy Epoch A 创建 Checkpoint，然后撤销或收窄相关权限，再在 Epoch B Resume。验收条件是 Useful State 可以保留，但旧 Authority 不可以跟着恢复。</p><p><strong>第二，测试 Compaction 之后的 Provenance。</strong> 压缩一段 Execution Transcript，并要求 Compact Representation 对每一个 Authority-sensitive Claim 都保留可解析 Evidence。如果 Summary 成了唯一剩下的“证据”，测试应失败。</p><p><strong>第三，测试 Authoritative Negative Evidence。</strong> 只从 Local Cache 删除一个 Resource，而不从 Source of Truth 删除。Runtime 应报告 Uncertainty 或 Stale Cache，而不是权威 Deletion。</p><p>现在的方向已经比“增加更多 Audit Log”更具体：长期 Agent 需要的是 <strong>Typed Trust Continuity</strong>。</p><p>Value 可以很新，却没有权限；Message 可以长得像真人回答，却不是 Human-authorized；Token 可以有效，却没完成 Durable Commit；Cache 可以为空，却不是 Authoritative；Checkpoint 可以最新，却不再可准入；Identifier 可以稳定，却还没有 Canonicalize。</p><p><strong>权限需要血缘链，因为 Persistence 保存 Data，远比它保存“为什么这些 Data 仍然可以安全用于行动”更容易。</strong></p>`,135))])}const g=t(l,[["render",p]]);export{b as __pageData,g as default};
